import { NextRequest, NextResponse } from 'next/server';
import { EdgeTTS } from 'node-edge-tts';
import { readFile, unlink } from 'fs/promises';
import path from 'path';
import { randomUUID } from 'crypto';

async function withTimeout(promise: any, ms: number | undefined) {
  return Promise.race([
    promise,
    new Promise((_, reject) => setTimeout(() => reject(new Error('TTS request timed out')), ms)),
  ]);
}

export async function POST(req: NextRequest) {
  const { text } = await req.json();

  const id = randomUUID();
  const audioFileName = `${id}.mp3`;
  const audioPath = path.join('/tmp', audioFileName);

  const tts = new EdgeTTS({
    voice: 'en-GB-RyanNeural',
    lang: 'en-GB',
    pitch: '+0Hz',
    rate: '+35%',
    volume: '+0%',
  });

  try {
    await tts.ttsPromise(text, audioPath);

    const audioBuffer = await readFile(audioPath);

    await unlink(audioPath);

    return new NextResponse(audioBuffer, {
      headers: {
        'Content-Type': 'audio/mpeg',
        'Content-Length': audioBuffer.length.toString(),
        'Accept-Ranges': 'bytes',
        'Cache-Control': 'no-cache',
      },
    });
  } catch (error) {
    console.error('TTS Error:', error);
    return NextResponse.json({ error: 'Failed to generate speech' }, { status: 500 });
  }
}

import { tools } from '@/constants';
import { NextRequest, NextResponse } from 'next/server'; import { writeFileSync } from "node:fs";
import OpenAI from "openai";

const openai = new OpenAI({
    apiKey: process.env.OPENAPI_API_KEY,
    baseURL: process.env.OPENAI_API_BASE_URL || "",
});
export async function POST(request: NextRequest) {
    let body: { text?: string } = {};
    try {
        body = await request.json();
    } catch {
        return NextResponse.json({ error: 'Invalid JSON body.' }, { status: 400 });
    }

    if (!body.text) {
        return NextResponse.json({ error: "Missing 'text' field in request body." }, { status: 400 });
    }

    try {
        const response = await openai.audio.speech.create({
            model: "openai-audio",
            voice: "nova",
            input: "Today is a wonderful day to build something people love!",
            response_format: "mp3",
        });

        const audioBase64 = response;
        console.log(audioBase64);

        if (!audioBase64) {
            return NextResponse.json(
                { error: 'No audio data returned from OpenAI.' },
                { status: 502 },
            );
        }

        return NextResponse.json({
            audio: audioBase64,
        });
    } catch (error: any) {
        return NextResponse.json({
            error: 'Error generating speech.',
            details: error?.message,
        }, { status: 500 });
    }
}

import { systemInstructions, tools } from '@/constants';
import { createOpenAICompatible } from '@ai-sdk/openai-compatible';
import { streamText, createDataStreamResponse } from 'ai';
import { google } from '@ai-sdk/google';

export const maxDuration = 30;

const provider = createOpenAICompatible({
  name: 'azure',
  apiKey: process.env.OPENAPI_API_KEY,
  baseURL: process.env.OPENAI_API_BASE_URL || "",
});

export async function POST(req: Request) {
  try {
    const { messages } = await req.json();

    const messagesHavePDF = messages.some(
      (message: { experimental_attachments: any[] }) =>
        message.experimental_attachments?.some(
          (a: { contentType: string }) => a.contentType === 'application/pdf'
        )
    );

    const model = messagesHavePDF
      ? google('gemini-2.5-flash-preview-04-17')
      : provider('openai-large');

    return createDataStreamResponse({
      execute: (dataStream) => {
        dataStream.writeData('initialized call');

        const result = streamText({
          model,
          system: systemInstructions,
          messages,
          tools,
          toolCallStreaming: true,
          maxSteps: 5,          
        });

        result.mergeIntoDataStream(dataStream);
      },
      onError: (error) => {
        return error instanceof Error ? error.message : String(error);
      },
    });
  } catch (error) {
    console.error('POST handler error:', error);

    return new Response(
      JSON.stringify({ error: 'An error occurred while processing the request.' }),
      { status: 500, headers: { 'Content-Type': 'application/json' } }
    );
  }
}

